<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get,write} from '../../../../packages/shared/src/client';import {useTask,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),overview=ref<Row>({}),rows=ref<Row[]>([]),page=ref(1),total=ref(0),freq=ref<Record<string,number>>({});
async function load(){await task.run(async()=>{const [summary,lessons]=await Promise.all([get<Row>('/learning-hub/overview'),get<Row>('/services/learning/lessons/page?pageNo='+page.value+'&pageSize=20')]);overview.value=summary;rows.value=lessons.list||[];total.value=Number(lessons.total||0);for(const row of rows.value)freq.value[row.id]=Number(summary.plans?.find((p:Row)=>String(p.courseId)===String(row.courseId))?.weekFreq||3);});}
async function save(row:Row){const ok=await task.run(async()=>{await write('/services/learning/lessons/plans','POST',{courseId:row.courseId,freq:freq.value[row.id]});return true;});if(ok){await load();task.message.value='学习计划已保存';}}
function expired(row:Row){return Number(row.status)===3||!!row.expireTime&&new Date(row.expireTime).getTime()<Date.now();}
onMounted(load);
</script><template><section class="learning-hub"><div class="section-heading"><div><h1>我的学习</h1><p>从上次停下的地方，继续向前。</p></div><RouterLink to="/">发现更多课程 →</RouterLink></div><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><div class="study-summary"><div><span>本周完成</span><strong>{{overview.weekFinished??0}} <small>小节</small></strong></div><div><span>本周计划</span><strong>{{overview.weekTotalPlan??0}} <small>小节</small></strong></div><div><span>本周积分</span><strong>{{overview.weekPoints??0}}</strong><RouterLink to="/points">查看积分 →</RouterLink></div><div><span>待完成考试</span><strong>{{overview.pendingExams??'查看'}}</strong><RouterLink to="/exams">前往考试 →</RouterLink></div></div><div class="study-shortcuts"><RouterLink to="/notes">私人笔记 →</RouterLink><RouterLink to="/review">错题复习 →</RouterLink><RouterLink to="/messages">回复与通知 →</RouterLink></div><div v-if="overview.continueLearning" class="card"><h2>接着上次学</h2><p>{{rows.find(row=>String(row.courseId)===String(overview.continueLearning.courseId))?.courseName||'最近学习的课程'}}</p><RouterLink class="hero-cta" :to="{path:'/courses/'+overview.continueLearning.courseId,query:{sectionId:overview.continueLearning.sectionId,moment:overview.continueLearning.moment}}">从上次进度继续 →</RouterLink></div><h2>继续学习</h2><div class="learning-list"><article v-for="row in rows" :key="row.id" class="card learning-row"><div><p>{{expired(row)?'学习权益已失效':Number(row.status)===2?'已学完':'学习中'}}</p><h3><RouterLink :to="'/courses/'+row.courseId">{{row.courseName}}</RouterLink></h3><p>已学 {{row.learnedSections||0}} / {{row.sections||0}} 小节</p><el-progress :percentage="row.sections?Math.min(100,Math.round(row.learnedSections/row.sections*100)):0"/></div><div class="learning-row-actions"><RouterLink class="hero-cta" :to="'/courses/'+row.courseId">{{expired(row)?'查看历史':'继续学习'}} →</RouterLink><details v-if="!expired(row)" class="study-plan"><summary>设置每周学习计划</summary><p>按小节安排本周目标</p><div class="toolbar"><el-input-number v-model="freq[row.id]" :min="1" :max="50" aria-label="每周学习小节数"/><span>小节 / 周</span><el-button @click="save(row)" :disabled="task.busy.value">保存计划</el-button></div></details></div></article></div><el-empty v-if="!task.busy.value&&!task.error.value&&!rows.length" description="还没有课程，选择一门开始吧"><RouterLink to="/">浏览课程 →</RouterLink></el-empty><el-pagination v-if="total>20" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/><section v-if="overview.recentAchievements?.length" class="card"><h2>最近获得的成就</h2><div class="achievement-list"><p v-for="item in overview.recentAchievements" :key="item.code"><strong>{{item.name}}</strong><span>{{item.awardedAt}}</span></p></div></section></section></template>